"use client";

import { useRef, useState } from "react";
import {
  RiAddLine,
  RiArrowUpLine,
  RiArrowDownSLine,
  RiFolder3Line,
  RiGitBranchLine,
  RiInfinityLine,
  RiMicLine,
} from "@remixicon/react";
import {
  Dropdown,
  DropdownPopover,
  DropdownTrigger,
} from "../../base/dropdown/dropdown";
import {
  ComposerRichInput,
  type ComposerRichInputHandle,
} from "../composer-panel/composer-rich-input";
import { cx } from "@/lib/utils";
import {
  EFFORT_LEVELS,
  EffortSlider,
  type EffortLevel,
} from "./effort-slider";

export type ComposerModel = {
  id: string;
  name: string;
};

const DEFAULT_MODELS: ComposerModel[] = [
  { id: "composer-2.5", name: "Composer 2.5" },
  { id: "gpt-5.6-sol", name: "GPT-5.6 Sol" },
  { id: "fable-5", name: "Fable 5" },
  { id: "sonnet-5", name: "Sonnet 5" },
];

/**
 * Style A — pill composer: single-row prompt with + / model / mic / send,
 * status row underneath (branch · project · agent · context), and a compact
 * model menu with radio list + liquid effort slider.
 */
export function Composer({
  models = DEFAULT_MODELS,
  defaultModelId = "fable-5",
  defaultEffort = 5,
  placeholder = "有什么问题就问我",
  branch = "主要",
  project = "项目海",
  agentMode = "智能体",
  contextPct = 57,
  className,
  defaultModelMenuOpen = true,
}: {
  models?: ComposerModel[];
  defaultModelId?: string;
  defaultEffort?: EffortLevel;
  placeholder?: string;
  branch?: string;
  project?: string;
  agentMode?: string;
  contextPct?: number;
  className?: string;
  /** Docs preview opens the model menu by default to match the reference. */
  defaultModelMenuOpen?: boolean;
}) {
  const inputRef = useRef<ComposerRichInputHandle>(null);
  const [modelId, setModelId] = useState(defaultModelId);
  const [effort, setEffort] = useState<EffortLevel>(defaultEffort);
  const [menuOpen, setMenuOpen] = useState(defaultModelMenuOpen);

  const model = models.find((m) => m.id === modelId) ?? models[0];
  const effortLabel = EFFORT_LEVELS[effort]?.label ?? "最大";

  const submit = () => {
    const text = inputRef.current?.getText().trim() ?? "";
    if (!text) return;
    inputRef.current?.clear();
  };

  return (
    <div className={cx("relative w-full max-w-xl", className)}>
      <div className="flex w-full flex-col gap-2.5">
        <form
          className={cx(
            "flex h-[52px] w-full items-center gap-2 rounded-full p-2",
            "bg-background-primary-default shadow-xs",
            "ring-1 ring-border-button-default/60",
          )}
          onSubmit={(e) => {
            e.preventDefault();
            submit();
          }}
        >
          <button
            type="button"
            aria-label="添加附件"
            className="flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full bg-ai-chat-composer-add-background text-foreground-icon-primary transition-colors hover:bg-ai-chat-composer-add-hover-background"
          >
            <RiAddLine className="size-5" aria-hidden />
          </button>

          <ComposerRichInput
            ref={inputRef}
            placeholder={placeholder}
            className={cx(
              "min-w-0 flex-1 overflow-hidden",
              "[&_[role=textbox]]:max-h-5 [&_[role=textbox]]:min-h-5",
              "[&_[role=textbox]]:overflow-hidden [&_p]:truncate",
            )}
            onSubmit={submit}
          />

          <Dropdown isOpen={menuOpen} onOpenChange={setMenuOpen}>
            <DropdownTrigger
              aria-label="选择模型"
              className={cx(
                "inline-flex h-8 shrink-0 cursor-pointer items-center gap-1 rounded-xl px-2",
                "text-body-2-medium text-text-secondary outline-none",
                "hover:bg-background-secondary-default",
                "focus-visible:ring-2 focus-visible:ring-border-focus-ring",
              )}
            >
              <span className="max-w-[12ch] truncate">{model?.name}</span>
              <RiArrowDownSLine
                className={cx(
                  "size-4 text-foreground-icon-tertiary transition-transform",
                  menuOpen && "rotate-180",
                )}
                aria-hidden
              />
            </DropdownTrigger>
            <DropdownPopover
              aria-label="型号"
              placement="top end"
              offset={10}
              className="w-[268px] rounded-2xl p-1.5 shadow-lg"
              dialogClassName="gap-0"
            >
              <p className="px-2 pb-1 pt-0.5 text-caption-1-medium text-text-tertiary">
                型号
              </p>
              <ul className="flex flex-col gap-0.5" role="listbox">
                {models.map((item) => {
                  const selected = item.id === modelId;
                  return (
                    <li key={item.id}>
                      <button
                        type="button"
                        role="option"
                        aria-selected={selected}
                        onClick={() => setModelId(item.id)}
                        className={cx(
                          "flex w-full cursor-pointer items-center gap-2.5 rounded-2lg px-2.5 py-2 text-start",
                          "text-body-medium outline-none transition-colors",
                          selected
                            ? "bg-background-secondary-hover text-text-primary"
                            : "text-text-secondary hover:bg-background-secondary-hover/70",
                        )}
                      >
                        <span
                          className={cx(
                            "inline-flex size-4 shrink-0 items-center justify-center rounded-full border-2",
                            selected
                              ? "border-accent-500"
                              : "border-border-button-default",
                          )}
                          aria-hidden
                        >
                          {selected ? (
                            <span className="size-2 rounded-full bg-accent-500" />
                          ) : null}
                        </span>
                        {item.name}
                      </button>
                    </li>
                  );
                })}
              </ul>

              <div className="mt-1.5 border-t border-separator-border px-1.5 pt-3 pb-1">
                <div className="mb-2 flex items-center justify-between px-0.5">
                  <span className="text-caption-1-medium text-text-tertiary">
                    努力
                  </span>
                  <span className="text-caption-1-medium text-text-secondary">
                    {effortLabel}
                  </span>
                </div>
                <EffortSlider value={effort} onChange={setEffort} />
              </div>
            </DropdownPopover>
          </Dropdown>

          <button
            type="button"
            aria-label="语音输入"
            className="flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full text-foreground-icon-secondary transition-colors hover:bg-background-secondary-default"
          >
            <RiMicLine className="size-5" aria-hidden />
          </button>

          <button
            type="submit"
            aria-label="发送"
            className="flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full bg-button-primary text-white shadow-xs"
          >
            <RiArrowUpLine className="size-5" aria-hidden />
          </button>
        </form>

        {/* Status lives under the pill — part of this style, not hanging pills */}
        <div className="flex h-[26px] w-full items-center justify-between gap-3 px-1">
          <div className="flex min-w-0 items-center gap-3">
            <StatusChip icon={RiGitBranchLine} label={branch} />
            <StatusChip icon={RiFolder3Line} label={project} chevron />
          </div>
          <div className="flex shrink-0 items-center gap-3">
            <StatusChip icon={RiInfinityLine} label={agentMode} chevron />
            <ContextMeter value={contextPct} />
          </div>
        </div>
      </div>
    </div>
  );
}

function StatusChip({
  icon: Icon,
  label,
  chevron,
}: {
  icon: typeof RiGitBranchLine;
  label: string;
  chevron?: boolean;
}) {
  return (
    <span className="inline-flex max-w-[12ch] items-center gap-1 text-body-2-medium text-text-secondary">
      <Icon
        className="size-4 shrink-0 text-foreground-icon-secondary"
        aria-hidden
      />
      <span className="truncate">{label}</span>
      {chevron ? (
        <RiArrowDownSLine
          className="size-3.5 shrink-0 text-foreground-icon-quaternary"
          aria-hidden
        />
      ) : null}
    </span>
  );
}

function ContextMeter({ value }: { value: number }) {
  const clamped = Math.max(0, Math.min(100, value));
  const r = 7;
  const c = 2 * Math.PI * r;
  const offset = c * (1 - clamped / 100);

  return (
    <span
      className="inline-flex items-center gap-1.5 text-body-2-medium text-text-secondary tabular-nums"
      title={`上下文 ${clamped}%`}
    >
      <svg width="18" height="18" viewBox="0 0 18 18" aria-hidden>
        <circle
          cx="9"
          cy="9"
          r={r}
          fill="none"
          stroke="var(--color-border-button-default)"
          strokeWidth="2"
        />
        <circle
          cx="9"
          cy="9"
          r={r}
          fill="none"
          stroke="var(--color-accent-500)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={c}
          strokeDashoffset={offset}
          transform="rotate(-90 9 9)"
        />
      </svg>
      {clamped}%
    </span>
  );
}

"use client";

import { cx } from "@/lib/utils";

/** Effort stops: 0 Faster … 5 Max (更聪明). */
export const EFFORT_LEVELS = [
  { id: 0, label: "更快" },
  { id: 1, label: "低" },
  { id: 2, label: "中" },
  { id: 3, label: "高" },
  { id: 4, label: "更高" },
  { id: 5, label: "最大" },
] as const;

export type EffortLevel = (typeof EFFORT_LEVELS)[number]["id"];

/**
 * Liquid effort rail — dark track with a cyan plasma fill that widens toward
 * Max, and a white thumb. Matches the JoyUI composer model menu look.
 */
export function EffortSlider({
  value,
  onChange,
  className,
}: {
  value: EffortLevel;
  onChange: (next: EffortLevel) => void;
  className?: string;
}) {
  const pct = (value / (EFFORT_LEVELS.length - 1)) * 100;

  return (
    <div className={cx("flex w-full flex-col gap-2", className)}>
      <div className="flex items-center justify-between px-0.5">
        <span className="text-caption-1-medium text-text-tertiary">更快</span>
        <span className="text-caption-1-medium text-text-tertiary">更聪明</span>
      </div>
      <div className="relative h-8 w-full">
        <div
          aria-hidden
          className="absolute inset-x-0 top-1/2 h-4 -translate-y-1/2 overflow-hidden rounded-full bg-[#0b1220] dark:bg-neutral-950"
        >
          <div
            className="absolute inset-y-0 start-0"
            style={{
              width: `${Math.max(pct, 10)}%`,
              background:
                "radial-gradient(ellipse 90% 140% at 92% 50%, #e0f2fe 0%, #7dd3fc 18%, #38bdf8 42%, #0284c7 72%, #0c4a6e 100%)",
              boxShadow:
                "0 0 22px rgba(56,189,248,0.65), 0 0 8px rgba(14,165,233,0.4) inset",
              borderRadius: "9999px",
            }}
          />
          <div
            className="pointer-events-none absolute inset-y-[2px] start-[2px] rounded-full opacity-80"
            style={{
              width: `calc(${Math.max(pct, 10)}% - 4px)`,
              background:
                "linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.08) 35%, rgba(255,255,255,0.55) 100%)",
              filter: "blur(0.5px)",
            }}
          />
        </div>
        <input
          type="range"
          min={0}
          max={EFFORT_LEVELS.length - 1}
          step={1}
          value={value}
          aria-label="努力"
          aria-valuetext={EFFORT_LEVELS[value]?.label}
          onChange={(e) => onChange(Number(e.target.value) as EffortLevel)}
          className={cx(
            "absolute inset-0 z-10 m-0 h-full w-full cursor-pointer appearance-none bg-transparent",
            "[&::-webkit-slider-thumb]:size-4 [&::-webkit-slider-thumb]:appearance-none",
            "[&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-2",
            "[&::-webkit-slider-thumb]:border-white [&::-webkit-slider-thumb]:bg-white",
            "[&::-webkit-slider-thumb]:shadow-[0_1px_4px_rgba(0,0,0,0.35)]",
            "[&::-moz-range-thumb]:size-4 [&::-moz-range-thumb]:rounded-full",
            "[&::-moz-range-thumb]:border-2 [&::-moz-range-thumb]:border-white",
            "[&::-moz-range-thumb]:bg-white [&::-moz-range-thumb]:shadow-[0_1px_4px_rgba(0,0,0,0.35)]",
          )}
        />
      </div>
    </div>
  );
}

"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useId, useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import { cx } from "@/lib/utils";

/**
 * Composer Loader — a loading state that wraps a chat composer while the agent
 * works: an iridescent light band orbiting the pill's rim with a soft bloom
 * bleeding inward.
 *
 * The band is dash segments on an SVG stroke of the pill shape
 * (pathLength-normalized, so it travels at constant speed and bends around
 * the end caps), drawn at three scales — crisp line, tight glow, wide bloom —
 * with the sharp line leading and every soft layer's head pulled back behind
 * the tip.
 *
 * The component paints the pill surface itself and layers the light above
 * it, so the wrapped composer must not paint its own background:
 *
 *   <ComposerLoader active={isWaitingForReply}>
 *     <Composer className="bg-transparent shadow-none" />
 *   </ComposerLoader>
 *
 * `active` fades the whole effect in and out (450ms), so toggling it on
 * send / reply reads as the composer lighting up rather than snapping.
 */

export interface ComposerLoaderProps {
  children: ReactNode;
  /** Show the light. Fades in/out — flip it while awaiting a response. */
  active?: boolean;
  /** Four gradient colors, spread across the pill left → right. */
  colors?: [string, string, string, string];
  /** Seconds per full lap. */
  speed?: number;
  /** Overall light opacity. */
  intensity?: number;
  /** How far the bloom bleeds inward from the rim, px. */
  bloom?: number;
  /** Bloom layer opacity. */
  bloomStrength?: number;
  /** How much of the perimeter the band occupies, degrees (of 360). */
  arc?: number;
  /** Reverse the travel direction. */
  reverse?: boolean;
  /** Corner radius, px. Defaults to a full pill. */
  radius?: number;
  /** Width of the crisp line, px; the tight glow scales with it. */
  line?: number;
  /** Draw the wide bloom alone, no line or tight glow: a soft wash for a beam to lead. */
  bloomOnly?: boolean;
  /** Paint the pill surface behind the light (on by default). */
  surface?: boolean;
  /**
   * Fade the band's two ends instead of cutting them, 0–1: the fraction of
   * the band's length that ramps. Each layer is stacked as shorter, centred
   * copies at a fraction of its opacity; the blur melts the steps together.
   */
  taper?: number;
  /** How the light composites over what's beneath, e.g. `screen` to read as light on a surface. */
  blend?: CSSProperties["mixBlendMode"];
  /**
   * Moves the band forward along the lap, as a fraction of the perimeter
   * (0–1). Lets two loaders on one pill line up: a short beam with
   * `offset` equal to the difference of the two arcs (as fractions) leads
   * a wider glow tip to tip.
   */
  offset?: number;
  className?: string;
}

const DEFAULT_COLORS: [string, string, string, string] = [
  "#5eead4",
  "#46baec",
  "#e633a4",
  "#00faa7",
];

function hexTriplet(hex: string) {
  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
}

export function ComposerLoader({
  children,
  active = true,
  colors = DEFAULT_COLORS,
  speed = 4.5,
  intensity = 0.7,
  bloom = 16,
  bloomStrength = 0.3,
  arc = 120,
  reverse = false,
  radius,
  line = 2.5,
  bloomOnly = false,
  surface = true,
  taper = 0,
  blend,
  offset = 0,
  className,
}: ComposerLoaderProps) {
  const localize = useTemplateCopy();
  const gradientId = `bui-cl-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
  const clipRef = useRef<HTMLSpanElement>(null);
  const [box, setBox] = useState({ w: 640, h: 52 });

  useEffect(() => {
    const el = clipRef.current;
    if (!el) return;
    const observer = new ResizeObserver(() =>
      setBox({ w: Math.max(1, el.clientWidth), h: Math.max(1, el.clientHeight) }),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const [c0, c1, c2, c3] = colors;
  // Gradient center: pure blend of the middle colors, so the band never
  // washes out to white.
  const mid = `rgb(${hexTriplet(c1)
    .map((v, i) => Math.round((v + hexTriplet(c2)[i]) / 2))
    .join(",")})`;

  const band = (arc / 360) * 100;
  const rx = radius ?? box.h / 2;
  const cornerRadius = radius ?? 9999;
  const direction = reverse ? "reverse" : "normal";

  // Path units per px, for pulling each soft layer's head behind the tip.
  // Rounded-rect perimeter: straight runs plus the four corner arcs (for the
  // default pill, rx = h/2 and this reduces to 2(w−h) + πh).
  const cornerR = Math.min(rx, box.w / 2, box.h / 2);
  const perimeter = Math.max(1, 2 * (box.w + box.h) - 8 * cornerR + 2 * Math.PI * cornerR);
  const pxUnits = (px: number) => (px * 100) / perimeter;
  // A layer's delay is its phase: the larger the phase, the further BACK
  // along the lap the band sits (a negative delay is a head start). So
  // moving a band forward, `offset` included, means subtracting.
  const dashPhase = (len: number, backPx: number) =>
    (reverse ? pxUnits(backPx) : len - band + pxUnits(backPx)) - offset * 100;

  // Tapering stacks each layer as shorter, centred copies: the ramp at each
  // end is a staircase with one step per copy, so it takes many copies and
  // a little blur on the crisp line for the steps to melt into a gradient.
  const TAPER_STEPS = 14;
  const CRISP_BLUR = taper > 0 ? Math.max(0.5, line * 0.8) : 0.5;
  const stroke = (width: number, blur: number, opacity: number, dashLen: number, backPx: number) => {
    const copies = taper > 0 ? TAPER_STEPS : 1;
    return Array.from({ length: copies }, (_, index) => {
      // Copy 0 is the full band; each next one is shorter and moved forward
      // by half the difference, so all of them share one midpoint and the
      // ends thin out step by step.
      const len = dashLen * (1 - (taper * index) / copies);
      const phase = dashPhase(dashLen, backPx) - (dashLen - len) / 2;
      return (
        <rect
          key={index}
          x={0}
          y={0}
          width={box.w}
          height={box.h}
          rx={rx}
          pathLength={100}
          fill="none"
          stroke={`url(#${gradientId})`}
          strokeWidth={width}
          strokeLinecap="round"
          strokeDasharray={`${len} ${100 - len}`}
          className="bui-composer-loader-rect"
          // SVG-native blur, not CSS filter: WebKit (iOS Safari and every iPhone
          // browser) ignores CSS filters on individual SVG elements, which
          // rendered the whole light razor-sharp on phones.
          filter={blur > 0 ? `url(#${gradientId}-b${String(blur).replace(".", "_")})` : undefined}
          style={{
            opacity: opacity / copies,
            animation: `bui-composer-loader-dash ${speed}s linear ${(phase * speed) / 100}s infinite ${direction}`,
          }}
        />
      );
    });
  };

  /** One feGaussianBlur per blur radius the layers use. The region is
   *  widened well past the stroke so the blur never clips at the filter
   *  bounds. */
  const blurFilter = (radius: number) => (
    <filter
      key={radius}
      id={`${gradientId}-b${String(radius).replace(".", "_")}`}
      x="-50%"
      y="-50%"
      width="200%"
      height="200%"
    >
      <feGaussianBlur stdDeviation={radius} />
    </filter>
  );

  return localize((
    <div className={cx("relative", className)}>
      {surface && (
        <span
          aria-hidden
          className="absolute inset-0 bg-background-primary-default shadow-xs"
          style={{ borderRadius: cornerRadius }}
        />
      )}

      <span
        ref={clipRef}
        aria-hidden
        className="pointer-events-none absolute inset-0 overflow-hidden"
        style={{
          borderRadius: cornerRadius,
          opacity: active ? 1 : 0,
          transition: "opacity 450ms ease",
          mixBlendMode: blend,
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox={`0 0 ${box.w} ${box.h}`}
          preserveAspectRatio="none"
          style={{ opacity: intensity }}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor={c0} />
              <stop offset="30%" stopColor={c1} />
              <stop offset="50%" stopColor={mid} />
              <stop offset="70%" stopColor={c2} />
              <stop offset="100%" stopColor={c3} />
            </linearGradient>
            {[14, 6, CRISP_BLUR].map(blurFilter)}
          </defs>
          {/* wide bloom bleeding inward (outer half clipped by the pill) */}
          {bloom > 0 && stroke(bloom * 2, 14, bloomStrength, band * 0.9, bloom + 16)}
          {/* tight glow */}
          {!bloomOnly && stroke(line * 3.2, 6, 0.8, band * 0.95, 10)}
          {/* crisp refraction line, tip leading */}
          {!bloomOnly && stroke(line, CRISP_BLUR, 1, band, 0)}
        </svg>
      </span>

      <div className="relative">{children}</div>
    </div>
  ));
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  RiCloseLine,
  RiFileExcel2Line,
  RiFileImageLine,
  RiFileLine,
  RiFileWord2Line,
} from "@remixicon/react";
import { motion } from "motion/react";
import { cx } from "@/lib/utils";

export type ComposerAttachmentKind =
  | "image"
  | "document"
  | "spreadsheet"
  | "file";

export type ComposerAttachment = {
  id: string;
  name: string;
  kind: ComposerAttachmentKind;
  /** Thumbnail for images (optional; success card still uses the type icon). */
  src?: string;
  /** 0–100. While below 100 the perimeter ring draws; at 100 shows 上传成功. */
  progress?: number;
};

const KIND_ICON = {
  image: RiFileImageLine,
  document: RiFileWord2Line,
  spreadsheet: RiFileExcel2Line,
  file: RiFileLine,
} as const;

/** Rounded-rect path starting at top-center, clockwise — same recipe as FileUpload. */
function ringPath(width: number, height: number, inset: number, radius: number) {
  const x0 = inset;
  const y0 = inset;
  const x1 = width - inset;
  const y1 = height - inset;
  const arc = (endX: number, endY: number) =>
    `A ${radius} ${radius} 0 0 1 ${endX} ${endY}`;

  return [
    `M ${width / 2} ${y0}`,
    `H ${x1 - radius}`,
    arc(x1, y0 + radius),
    `V ${y1 - radius}`,
    arc(x1 - radius, y1),
    `H ${x0 + radius}`,
    arc(x0, y1 - radius),
    `V ${y0 + radius}`,
    arc(x0 + radius, y0),
    "Z",
  ].join(" ");
}

function AttachmentTile({
  file,
  onRemove,
  delay = 0,
}: {
  file: ComposerAttachment;
  onRemove?: (id: string) => void;
  delay?: number;
}) {
  const boxRef = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState({ width: 108, height: 96 });
  const [progress, setProgress] = useState(
    file.progress === 0 ? 0 : (file.progress ?? 100),
  );
  const Icon = KIND_ICON[file.kind];
  const done = progress >= 100;
  const path = ringPath(box.width, box.height, 1, 11);

  useEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      if (width > 0 && height > 0) setBox({ width, height });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    if (file.progress !== 0 && file.progress !== undefined) {
      setProgress(file.progress);
      return;
    }
    if (file.progress === 0) {
      setProgress(0);
      let raf = 0;
      const start = window.setTimeout(() => {
        const began = performance.now();
        const duration = 900 + delay * 180;
        const tick = (now: number) => {
          const t = Math.min(1, (now - began) / duration);
          setProgress(Math.round(t * 100));
          if (t < 1) raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      }, delay * 120);
      return () => {
        window.clearTimeout(start);
        cancelAnimationFrame(raf);
      };
    }
  }, [file.progress, delay]);

  return (
    <motion.div
      initial={{ opacity: 0, y: 6, scale: 0.96 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ delay: delay * 0.08, duration: 0.24, ease: "easeOut" }}
      className="group relative shrink-0 pt-2"
    >
      <div
        ref={boxRef}
        className={cx(
          "relative flex h-24 w-[108px] flex-col items-center justify-center gap-1.5",
          "rounded-xl bg-background-primary-default px-2",
        )}
      >
        <svg
          aria-hidden
          viewBox={`0 0 ${box.width} ${box.height}`}
          preserveAspectRatio="none"
          className="pointer-events-none absolute inset-0 size-full"
        >
          <rect
            x={1}
            y={1}
            width={box.width - 2}
            height={box.height - 2}
            rx={11}
            fill="none"
            stroke="var(--color-border-button-default)"
            strokeWidth={1.5}
          />
          <path
            d={path}
            fill="none"
            stroke={done ? "var(--color-yellow-400)" : "var(--color-accent-400)"}
            strokeWidth={1.5}
            strokeLinecap="round"
            pathLength={100}
            strokeDasharray={`${done ? 102 : progress} 200`}
            className="transition-[stroke-dasharray] duration-200 ease-linear"
          />
        </svg>

        <div
          aria-hidden
          className={cx(
            "absolute -top-2 left-1/2 z-10 -translate-x-1/2 rounded px-1 py-px",
            "text-[10px] font-medium leading-3 whitespace-nowrap text-white tabular-nums",
            done ? "bg-yellow-400" : "bg-accent-400",
          )}
        >
          {progress}%
        </div>

        <span className="relative flex size-7 items-center justify-center rounded-full border border-border-button-default bg-background-primary-default">
          <Icon
            className="size-3.5 shrink-0 text-foreground-icon-secondary"
            aria-hidden
          />
        </span>

        <div className="relative flex max-w-full flex-col items-center gap-0.5 px-0.5 text-center">
          <p className="max-w-full truncate text-caption-1-medium text-text-primary">
            {file.name}
          </p>
          <p className="text-[10px] leading-3 text-text-secondary">
            {done ? "上传成功" : "上传中…"}
          </p>
        </div>

        {onRemove ? (
          <button
            type="button"
            aria-label={`移除 ${file.name}`}
            onClick={() => onRemove(file.id)}
            className={cx(
              "absolute -end-1 -top-1 z-20 flex size-4 cursor-pointer items-center justify-center rounded-full",
              "bg-background-primary-default text-foreground-icon-secondary shadow-xs",
              "ring-1 ring-border-button-default opacity-0 transition-opacity group-hover:opacity-100",
            )}
          >
            <RiCloseLine className="size-3" aria-hidden />
          </button>
        ) : null}
      </div>
    </motion.div>
  );
}

